const page = figma.root.children.find(p => /Icons/i.test(p.name));
await figma.setCurrentPageAsync(page);

const collections = await figma.variables.getLocalVariableCollectionsAsync();
let iconDefault = null;
for (const coll of collections) {
  for (const id of coll.variableIds) {
    const v = await figma.variables.getVariableByIdAsync(id);
    if (v && v.name === 'icon/default') iconDefault = v;
  }
}
if (!iconDefault) throw new Error('icon/default missing');

function bindFills(root) {
  const stack = [root];
  while (stack.length) {
    const n = stack.pop();
    if ('constraints' in n) n.constraints = { horizontal: 'SCALE', vertical: 'SCALE' };
    if (n.type === 'VECTOR' || n.type === 'BOOLEAN_OPERATION' || n.type === 'ELLIPSE' || n.type === 'STAR' || n.type === 'POLYGON') {
      const paint = figma.variables.setBoundVariableForPaint(
        { type: 'SOLID', color: { r: 0, g: 0, b: 0 } }, 'color', iconDefault);
      n.fills = [paint];
      n.strokes = [];
    }
    if ('children' in n) for (const c of n.children) stack.push(c);
  }
}

function fitIn16(node) {
  // Scale glyph to fill ~15px inside 16 box, centered
  const pad = 0.5;
  const target = 16 - pad * 2;
  const bw = node.width || 1;
  const bh = node.height || 1;
  const scale = Math.min(target / bw, target / bh);
  node.resize(bw * scale, bh * scale);
  node.x = (16 - node.width) / 2;
  node.y = (16 - node.height) / 2;
}

const results = [];
for (const item of ITEMS) {
  const xs = await figma.getNodeByIdAsync(item.xsId);
  if (!xs) { results.push({ id: item.xsId, ok: false, reason: 'missing' }); continue; }
  for (const c of [...xs.children]) c.remove();
  const node = figma.createNodeFromSvg(item.svg);
  node.name = item.frameName;
  // Prefer resize SVG frame to 16x16 then bind
  try { node.resize(16, 16); } catch (_) {}
  node.x = 0; node.y = 0;
  node.clipsContent = false;
  if ('constraints' in node) node.constraints = { horizontal: 'SCALE', vertical: 'SCALE' };
  xs.appendChild(node);
  bindFills(node);
  // If single vector child, fit it; if frame with vectors, resize frame to 16
  try { xs.resizeWithoutConstraints(16, 16); } catch (_) { try { xs.resize(16, 16); } catch (__) {} }
  xs.clipsContent = false;
  // Ensure xs stays available for badge instances
  xs.visible = true;
  results.push({ id: item.xsId, name: xs.name, frame: item.frameName, kids: xs.children.map(c => c.name), ok: true });
}
return { results };
